window.CC.p.push({n:15,view:"<section class=\"view\" id=\"p15\" hidden style=\"--c:#00695c\"><h1><i>15</i>Lab &amp; Drug Interactions</h1><p class=\"lead\">16 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 15A</h3><div class=\"card\" data-u=\"u375\"><button class=\"open\" data-u=\"u375\"><b>Overview</b><span>Essential Laboratory Interpretation Mastery</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Essential+Laboratory+Interpretation+Mastery+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u376\"><button class=\"open\" data-u=\"u376\"><b>Module 1</b><span>Complete Blood Count (CBC) &amp; Peripheral Smear</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Complete+Blood+Count+%28CBC%29+%26+Peripheral+Smear+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u377\"><button class=\"open\" data-u=\"u377\"><b>Module 2</b><span>Inflammatory Markers (ESR VS. CRP VS. PROCALCITONIN)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Inflammatory+Markers+%28ESR+VS.+CRP+VS.+PROCALCITONIN%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u378\"><button class=\"open\" data-u=\"u378\"><b>Module 3</b><span>Coagulation Profile (PT/INR, aPTT, D-DIMER &amp; DIC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Coagulation+Profile+%28PT%2FINR%2C+aPTT%2C+D-DIMER+%26+DIC%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u379\"><button class=\"open\" data-u=\"u379\"><b>Module 4</b><span>Liver Function Tests (LFTs)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Liver+Function+Tests+%28LFTs%29+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u380\"><button class=\"open\" data-u=\"u380\"><b>Module 5</b><span>Kidney Function Tests (KFTs) &amp; Urinalysis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Kidney+Function+Tests+%28KFTs%29+%26+Urinalysis+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u381\"><button class=\"open\" data-u=\"u381\"><b>Module 6</b><span>Serum Electrolytes &amp; Minerals</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Serum+Electrolytes+%26+Minerals+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u382\"><button class=\"open\" data-u=\"u382\"><b>Module 7</b><span>Cardiac &amp; Endocrine Biomarkers</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiac+%26+Endocrine+Biomarkers+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u383\"><button class=\"open\" data-u=\"u383\"><b>Module 8</b><span>Autoimmune &amp; Serology Quick Reference</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Autoimmune+%26+Serology+Quick+Reference+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 15B</h3><div class=\"card\" data-u=\"u384\"><button class=\"open\" data-u=\"u384\"><b>Overview</b><span>Crucial &amp; Potentially Fatal Drug Interactions</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Crucial+%26+Potentially+Fatal+Drug+Interactions+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u385\"><button class=\"open\" data-u=\"u385\"><b>Module 1</b><span>Cardiovascular &amp; Antithrombotic Interactions</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiovascular+%26+Antithrombotic+Interactions+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u386\"><button class=\"open\" data-u=\"u386\"><b>Module 2</b><span>Renal, Electrolyte &amp; Immunosuppressant Interactions</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Renal%2C+Electrolyte+%26+Immunosuppressant+Interactions+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u387\"><button class=\"open\" data-u=\"u387\"><b>Module 3</b><span>Qtc Prolongation &amp; Torsades DE Pointes Combinations</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Qtc+Prolongation+%26+Torsades+DE+Pointes+Combinations+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u388\"><button class=\"open\" data-u=\"u388\"><b>Module 4</b><span>CNS, Psychiatric, Antimicrobial &amp; Pain Interactions</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=CNS%2C+Psychiatric%2C+Antimicrobial+%26+Pain+Interactions+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u389\"><button class=\"open\" data-u=\"u389\"><b>Module 5</b><span>Statins, Fluoroquinolones, Chelation &amp; Oral Contraceptive Traps</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Statins%2C+Fluoroquinolones%2C+Chelation+%26+Oral+Contraceptive+Traps+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u390\"><button class=\"open\" data-u=\"u390\"><b>Module 6</b><span>Master CYP450 Table, Drug-Disease Contraindications &amp; Pregnancy Teratogens</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Master+CYP450+Table%2C+Drug-Disease+Contraindications+%26+Pregnancy+Teratogens+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u375\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Overview</span><h1>Essential Laboratory Interpretation Mastery</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Essential+Laboratory+Interpretation+Mastery+medical\">🔍 Search on Google</a></header><h4><i><b>A Physician’s Clinical Guide to Reading Beyond the Numbers</b></i></h4><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u376\">Module 1 →</button></nav></article><article class=\"view unit\" id=\"u376\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 1</span><h1>Complete Blood Count (CBC) &amp; Peripheral Smear</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Complete+Blood+Count+%28CBC%29+%26+Peripheral+Smear+medical\">🔍 Search on Google</a></header><h3><b>1. Red Blood Cell (RBC) Parameters &amp; Hemoglobin (Hb)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Parameter</b></p></th><th><p><b>Adult Normal Reference Range</b></p></th><th><p><b>Key Clinical Meaning &amp; Traps</b></p></th></tr><tr><td><p><b>Hemoglobin (Hb)</b></p></td><td><p><b>Men:</b> 13.5 – 17.5 g/dL</p>\n<p><b>Women:</b> 12.0 – 15.5 g/dL</p>\n<p><b>Pregnant:</b> ≥ 11.0 g/dL (≥ 10.5 in 2nd trim)</p></td><td><p><b>CRITICAL TRAP #1 (Acute Bleed):</b> In acute hemorrhage, <mark class=\"hl lab\"><b>initial Hb is FALSELY NORMAL </b></mark>because whole blood (plasma + RBCs) is lost equally! Hb drops only hours later after fluid shifts/resuscitation!</p>\n<p><b>CRITICAL TRAP #2 (Hemodilution vs. Dehydration):</b> Pregnancy/fluid overload falsely lowers Hb; severe dehydration falsely elevates Hb!</p></td></tr><tr><td><p><b>Hematocrit (Hct)</b></p></td><td><p><b>Men:</b> 41 – 50% | <b>Women:</b> 36 – 44%</p></td><td><p>Usually ~3 × Hb. High Hct (&gt; 52% men / &gt; 48% women) = <mark class=\"hl lab\"><b>Polycythemia</b></mark> !</p></td></tr><tr><td><p><b>MCV</b> <i>(Mean Corpuscular Volume)</i></p></td><td><p><b>80 – 100 fL</b></p></td><td><p>Guides <b>Morphologic Classification of Anemia</b> (Microcytic &lt; 80 | Normocytic 80–100 | Macrocytic &gt; 100)!</p></td></tr><tr><td><p><b>RDW</b> <i>(Red Cell Distribution Width)</i></p></td><td><p><b>11.5 – 14.5%</b></p></td><td><p>Measures <b>anisocytosis</b> (variation in RBC size): <mark class=\"hl lab\"><b>High in IDA, B12/Folate deficiency, Mixed anemia</b></mark> ; <b>NORMAL in Thalassemia Trait</b>!</p></td></tr><tr><td><p><b>Reticulocyte Count</b> <i>(Corrected / Retic Index)</i></p></td><td><p><b>0.5 – 2.5%</b> <i>(Absolute: 25,000–75,000/µL)</i></p></td><td><p><b>MOST IMPORTANT FIRST STEP IN ANEMIA!</b> <b>High (&gt; 2–3%)</b> = Healthy bone marrow responding to <b>Hemolysis or Acute Blood Loss</b>! <b>Low (&lt; 2%)</b> = <b>Bone Marrow Underproduction</b> (IDA, B12, CKD, Aplastic anemia, Leukemia)!</p></td></tr></table><h3><b>2. Diagnostic Algorithm for Anemia (Separated by MCV!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Microcytic Anemia (MCV &lt; 80 fL — Mnemonic: \"TAILS\"):</b></span></p>\n<ul>\n<li class=\"l2\"><b>T</b>halassemia Trait (<i>Mentzer Index = MCV ÷ RBC &lt; 13</i>, normal RDW, normal Ferritin -&gt; confirm via Hb Electrophoresis!).</li>\n<li class=\"l2\"><b>A</b>nemia of Chronic Disease / Inflammation (can be normocytic early, microcytic late; <b>Low Iron + Low TIBC + High/Normal Ferritin</b>!).</li>\n<li class=\"l2\"><b>I</b>ron Deficiency Anemia (<mark class=\"hl lab\"><b> IDA — Low Ferritin [&lt; 15–30 ng/mL], Low Iron, High TIBC, High RDW!</b></mark> ).</li>\n<li class=\"l2\"><b>L</b>ead Poisoning (basophilic stippling on smear, abdominal colic, wrist/foot drop!).</li>\n<li class=\"l2\"><b>S</b>ideroblastic Anemia (ringed sideroblasts, high iron/ferritin — Alcohol, Isoniazid, MDS).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Normocytic Anemia (MCV 80–100 fL — Check Reticulocytes FIRST!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>High Reticulocytes (&gt; 2–3%):</i> <b>Acute Blood Loss</b> OR <b>Hemolytic Anemia</b> (High <mark class=\"hl mech\"><b>LDH</b></mark> , High <b>Indirect Bilirubin</b>, <b>Low Haptoglobin</b> -&gt; check <b>Direct Coombs Test </b>[autoimmune], G6PD, Sickle cell, Schistocytes [TTP/HUS/DIC]!).</li>\n<li class=\"l2\"><i>Low Reticulocytes (&lt; 2%):</i> <b>Anemia of Chronic Disease</b>, <mark class=\"hl lab\"><b>CKD</b></mark> (low Erythropoietin), Early IDA, <mark class=\"hl lab\"><b>Hypothyroidism</b></mark> , Bone marrow infiltration/failure!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Macrocytic Anemia (MCV &gt; 100 fL):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Megaloblastic (Hypersegmented Neutrophils ≥ 5 lobes on smear!):</i> <mark class=\"hl rx\"><b>Vitamin B12 Deficiency</b></mark> (high MMA + homocysteine) &amp; <b>Folate Deficiency</b> (high homocysteine ONLY!).</li>\n<li class=\"l2\"><i>Non-Megaloblastic (Round macrocytes, NO hypersegmented neutrophils):</i> <b>Alcoholism</b>, <b>Liver Disease</b>, <mark class=\"hl lab\"><b>Hypothyroidism</b></mark> , <b>Reticulocytosis</b> (large young retics raise MCV!), Drugs (<mark class=\"hl rx\"><b> Methotrexate, Hydroxyurea, Phenytoin</b></mark> ), <b>MDS</b> (Myelodysplastic Syndrome).</li>\n</ul><h3><b>3. White Blood Cell (WBC) Count &amp; Differential (Normal: 4,000 – 11,000/µL)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Cell Type</b></p></th><th><p><b>Normal % / Absolute</b></p></th><th><p><b>Causes of ELEVATION (Separated!)</b></p></th><th><p><b>Causes of DEPRESSION</b></p></th></tr><tr><td><p><b>Neutrophils</b></p></td><td><p>40 – 70% (1,800 – 7,700/µL)</p></td><td><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Acute Bacterial Infection</b> (plus <b>\"Left Shift\"</b> = toxic granulation &amp; immature band forms!)</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Corticosteroids</b></mark> (demarginates neutrophils!)</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\">Physical stress, Trauma, Smoking, <mark class=\"hl lab\"><b>CML</b></mark></span></p></td><td><p><b>Severe Sepsis</b> (consumption!), <b>Viral infections</b>, <mark class=\"hl rx\"><b>Chemotherapy / Clozapine / Carbimazole / Methimazole</b></mark> (<mark class=\"hl lab\"><b> ANC &lt; 500 = Febrile Neutropenia Emergency!</b></mark> ), Hypersplenism</p></td></tr><tr><td><p><b>Lymphocytes</b></p></td><td><p>20 – 45% (1,000 – 4,800/µL)</p></td><td><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Viral Infections</b> (<b>EBV</b>, CMV, Hepatitis — <i>atypical lymphocytes!</i>) 2. <b>Pertussis</b> (marked lymphocytosis!)</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>CLL</b></mark> (elderly + <b>\"Smudge Cells\"</b>!)</span></p></td><td><p><b>HIV/AIDS</b> (low CD4), Corticosteroids, <b>COVID-19</b>, Acute stress, Immunosuppression</p></td></tr><tr><td><p><b>Eosinophils</b></p></td><td><p>1 – 6% (&lt; 500/µL)</p></td><td><p><b>Mnemonic \"NAACP\":</b> <b>N</b>eoplasms (Hodgkin), <b>A</b>llergies/Asthma/<b>ABPA</b>, <b>A</b>drenal insufficiency (Addison’s!), <b>C</b>onnective tissue/Vasculitis (<b>EGPA/Churg-Strauss</b>), <b>P</b>arasites (<i>Schistosoma</i>, <i>Ascaris</i>, <i>Strongyloides</i>) &amp; <mark class=\"hl lab\"><b>DRESS Syndrome</b></mark> !</p></td><td><p>Steroids, Acute bacterial sepsis</p></td></tr><tr><td><p><b>Monocytes</b></p></td><td><p>2 – 8%</p></td><td><p>Chronic infections (<b>TB, Brucellosis, Endocarditis</b>), IBD, Recovery from neutropenia</p></td><td><p>Hairy cell leukemia</p></td></tr></table><h3><b>4. Platelets (Normal: 150,000 – 450,000/µL)</b></h3><ul>\n<li class=\"l1\"><b>Bleeding Risk Thresholds:</b> &lt; 50,000 (surgical bleeding risk) | &lt; 20,000 (mucocutaneous wet bleeding) | &lt; 10,000 (risk of spontaneous <b>Intracranial Hemorrhage</b>!).</li>\n<li class=\"l1\"><b>TRAP — Pseudothrombocytopenia:</b> Always review a <b>Peripheral Blood Smear</b> before diagnosing isolated low platelets -&gt; <b>EDTA-anticoagulant clumping</b> falsely drops automated platelet counts (recheck in <b>Citrate [blue-top]</b> tube!).</li>\n<li class=\"l1\"><b>Separated Causes of True Thrombocytopenia:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i>Decreased Production:</i> Leukemia, Aplastic anemia, Chemo, <b>B12/Folate deficiency</b>, Alcohol, Sepsis.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>Increased Peripheral Destruction:</i> <mark class=\"hl lab\"><b>ITP</b></mark> , <mark class=\"hl lab\"><b>TTP / HUS</b></mark> , <b>DIC</b>, <b>HIT</b> (Heparin-Induced Thrombocytopenia — drops &gt; 50% Days 5–10 on Heparin!), <mark class=\"hl lab\"><b>HELLP</b></mark> , <mark class=\"hl lab\"><b>SLE/APS</b></mark> , Drugs (Quinine, Vancomycin, TMP-SMX).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i>Sequestration:</i> <b>Hypersplenism</b> (Liver Cirrhosis — classic early clue to portal hypertension!).</span></p>\n<ul>\n<li class=\"l1\"><b>Causes of Thrombocytosis (&gt; 450,000):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i>Reactive (Secondary — ~85%):</i> <b>Iron Deficiency Anemia</b>, Acute/Chronic Inflammation/Infection (<b>Kawasaki Disease!</b>), Post-splenectomy, Malignancy.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>Primary Clonal:</i> <b>Essential Thrombocythemia</b> (<i>JAK2</i> mutation -&gt; risk of both thrombosis AND bleeding!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u375\">← Overview</button><button class=\"nv\" data-u=\"u377\">Module 2 →</button></nav></article><article class=\"view unit\" id=\"u377\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 2</span><h1>Inflammatory Markers (ESR VS. CRP VS. PROCALCITONIN)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Inflammatory+Markers+%28ESR+VS.+CRP+VS.+PROCALCITONIN%29+medical\">🔍 Search on Google</a></header><table class=\"t \"><tr class=\"hd\"><th><p><b>Marker</b></p></th><th><p><b>What It Actually Measures &amp; Kinetics</b></p></th><th><p><b>Normal Range</b></p></th><th><p><b>Clinical Pearls &amp; Traps (READ CAREFULLY!)</b></p></th></tr><tr><td><p><mark class=\"hl mech\"><b>ESR</b></mark> <i>(Erythrocyte Sedimentation Rate)</i></p></td><td><p>Indirectly measures <b>Fibrinogen</b> &amp; Immunoglobulins (which neutralize negative RBC charge causing <b>Rouleaux</b> stacking -&gt; fall faster!)</p>\n<p><b>SLOW kinetics:</b> Rises in <b>24–48 hrs</b>, stays high for <b>weeks</b>!</p></td><td><p><b>Men:</b> &lt; Age ÷ 2</p>\n<p><b>Women:</b> &lt; (Age + 10) ÷ 2 <i>(General: &lt; 15–20 mm/hr)</i></p></td><td><p><b>Falsely HIGH:</b> <mark class=\"hl lab\"><b>Anemia</b></mark> (fewer RBCs fall faster!), Pregnancy, Advancing age, Obesity, <mark class=\"hl lab\"><b>Multiple Myeloma</b></mark> (massive IgG/IgM -&gt; ESR &gt; 100!), Nephrotic syndrome.</p>\n<p><b>Falsely LOW/NORMAL:</b> <mark class=\"hl lab\"><b>Polycythemia</b></mark> , <b>Sickle Cell Disease</b> (sickled cells can’t stack into rouleaux!), Severe Heart Failure / Hypofibrinogenemia (DIC)! <b>Classic Uses:</b> <mark class=\"hl lab\"><b>GCA / PMR</b></mark> (&gt; 50–100), Osteomyelitis, TB, SLE (note: in active <mark class=\"hl lab\"><b>SLE flare</b></mark> , <mark class=\"hl mech\"><b>ESR rises while CRP often stays NORMAL</b></mark> unless infection/serositis exists!).</p></td></tr><tr><td><p><mark class=\"hl mech\"><b>CRP</b></mark> <i>(C-Reactive Protein)</i></p></td><td><p>Direct hepatic <b>Acute-Phase Reactant</b> induced by <b>IL-6</b></p>\n<p><mark class=\"hl mech\"><b>FAST kinetics:</b></mark> Rises within <b>6–12 hours</b>, peaks at <b>48 hours</b>, drops rapidly once resolved!</p></td><td><p><b>&lt; 5 mg/L (or &lt; 0.5–1.0 mg/dL)</b></p>\n<p class=\"muted\"><i>(hs-CRP &lt; 1–3 mg/L for CV risk)</i></p></td><td><p><b>MUCH MORE SENSITIVE &amp; SPECIFIC</b> than ESR for <b>acute inflammation, bacterial infection, and monitoring antibiotic response!</b> NOT affected by anemia, age, or RBC shape!</p></td></tr><tr><td><p><b>Procalcitonin (PCT)</b></p></td><td><p>Precursor of calcitonin released by systemic parenchymal cells specifically in response to <b>bacterial endotoxins &amp; TNF-α</b> (<b>inhibited by viral Interferon-gamma!</b>)</p></td><td><p><b>&lt; 0.1 ng/mL</b> <i>(Sepsis likely &gt; 0.5–2.0 ng/mL)</i></p></td><td><p><b>Distinguishes BACTERIAL Sepsis vs. Viral/Sterile inflammation!</b> Best used to <b>GUIDE WHEN TO STOP ANTIBIOTICS</b> (e.g., drop &gt; 80% or &lt; 0.25–0.5 ng/mL in CAP/ICU sepsis!).</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u376\">← Module 1</button><button class=\"nv\" data-u=\"u378\">Module 3 →</button></nav></article><article class=\"view unit\" id=\"u378\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 3</span><h1>Coagulation Profile (PT/INR, aPTT, D-DIMER &amp; DIC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Coagulation+Profile+%28PT%2FINR%2C+aPTT%2C+D-DIMER+%26+DIC%29+medical\">🔍 Search on Google</a></header><h3><b>1. Core Tests &amp; Pathways</b></h3><ul>\n<li class=\"l1\"><b>PT</b> (Prothrombin Time, 11–13.5 sec) &amp; <mark class=\"hl mech\"><b>INR</b></mark> (International Normalized Ratio, Normal: 0.8 – 1.2): Measures <b>Extrinsic (Factor VII) &amp; Common Pathways (X, V, II, I)</b>.</li>\n<li class=\"l2\"><b>Clinical Uses:</b> Monitoring <mark class=\"hl rx\"><b>Warfarin</b></mark> (Target <mark class=\"hl mech\"><b>INR 2.0–3.0</b></mark> for AFib/DVT/PE; <b>2.5–3.5</b> for Mechanical Mitral Valve!), <b>Liver Synthetic Function</b> (<b>MELD / Child-Pugh </b>— Factor VII has the shortest half-life [~6 hrs], so <mark class=\"hl mech\"><b>PT/INR is the EARLIEST marker of acute liver failure!</b></mark> ), <b>Vitamin K Deficiency</b>.</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>aPTT</b></mark> (Activated Partial Thromboplastin Time, 25–35 sec): Measures <b>Intrinsic (Factors XII, XI, IX, VIII) &amp; Common Pathways</b>.</li>\n<li class=\"l2\"><b>Clinical Uses:</b> Monitoring <mark class=\"hl rx\"><b>IV Unfractionated Heparin (UFH)</b></mark> (Target 1.5–2.5× control), Screening for <mark class=\"hl lab\"><b>Hemophilia A (VIII) &amp; B (IX)</b></mark> , <b>vWD</b>, and <mark class=\"hl lab\"><b>Lupus Anticoagulant (APS)</b></mark> !</li>\n<li class=\"l1\"><b>D-Dimer</b> (Normal: &lt; 500 ng/mL FEU or age-adjusted Age × 10 if &gt; 50 yrs): Fibrin degradation product confirming active <b>clot formation AND fibrinolysis</b>.</li>\n<li class=\"l2\"><b>CRITICAL RULE:</b> <b>HIGH Sensitivity, VERY LOW Specificity!</b> A <b>NEGATIVE D-Dimer</b> in a <i>low/intermediate-risk</i> patient <mark class=\"hl lab\"><b>RULES OUT DVT / PE</b></mark> ; a <b>POSITIVE D-Dimer </b>NEVER confirms DVT/PE (elevated in infection, surgery, pregnancy, cancer, trauma, liver disease, elderly!).</li>\n</ul><h3><b>2. Diagnostic Pattern Matrix (Memorize This Table!)</b></h3><table class=\"t wide\"><tr class=\"hd\"><th><p><b>Condition</b></p></th><th><p><b>Platelets</b></p></th><th><p><mark class=\"hl mech\"><b>PT / INR</b></mark></p></th><th><p><mark class=\"hl mech\"><b>aPTT</b></mark></p></th><th><p><b>Fibrinogen / D-Dimer</b></p></th><th><p><b>Key Clinical Pearl</b></p></th></tr><tr><td><p><mark class=\"hl lab\"><b>ITP</b></mark> <i>(Platelet Disorder)</i></p></td><td><p><b>VERY LOW</b></p></td><td><p>Normal</p></td><td><p>Normal</p></td><td><p>Normal</p></td><td><p>Mucocutaneous petechiae/purpura</p></td></tr><tr><td><p><mark class=\"hl lab\"><b>Hemophilia A / B</b></mark> <i>(VIII / IX)</i></p></td><td><p>Normal</p></td><td><p>Normal</p></td><td><p><b>PROLONGED</b></p></td><td><p>Normal</p></td><td><p>Deep hemarthrosis/muscle bleeds; <b>Correction on Mixing Study!</b></p></td></tr><tr><td><p><mark class=\"hl rx\"><b>Warfarin / Vitamin K Def. / Early Liver Disease</b></mark></p></td><td><p>Normal <i>(Low in cirrhosis)</i></p></td><td><p><mark class=\"hl mech\"><b>PROLONGED (High INR!)</b></mark></p></td><td><p>Normal <i>(or mild ↑ late)</i></p></td><td><p>Normal</p></td><td><p>Vitamin K corrects dietary/cholestatic deficiency within 24 hrs; <b>does NOT correct severe cirrhosis</b>!</p></td></tr><tr><td><p><mark class=\"hl lab\"><b>Heparin (UFH) / Lupus Anticoagulant (APS)</b></mark></p></td><td><p>Normal <i>(Watch for HIT!)</i></p></td><td><p>Normal</p></td><td><p><b>PROLONGED</b></p></td><td><p>Normal</p></td><td><p><mark class=\"hl lab\"><b>APS Mixing Study FAILS to correct </b></mark>(causes <b>THROMBOSIS</b>, NOT bleeding, in vivo!)</p></td></tr><tr><td><p><b>vWD</b> <i>(von Willebrand Disease)</i></p></td><td><p>Normal</p></td><td><p>Normal</p></td><td><p>Normal or <b>Mildly ↑</b></p></td><td><p>Normal <i>(↑ Bleeding Time / PFA-100)</i></p></td><td><p>#1 inherited bleeding disorder; mucocutaneous bleed + prolonged epistaxis/menorrhagia!</p></td></tr><tr><td><p><b>DIC</b> <i>(Disseminated Intravascular Coagulation)</i></p></td><td><p><b>LOW</b></p></td><td><p><b>PROLONGED</b></p></td><td><p><b>PROLONGED</b></p></td><td><p><b>LOW Fibrinogen (&lt; 100) + VERY HIGH D-Dimer</b></p></td><td><p><mark class=\"hl dx\"><b>Schistocytes</b></mark> on smear! Triggered by <b>Sepsis, Abruption, Trauma, Malignancy (APL)!</b></p></td></tr></table><h3><b>3. Warfarin Over-Anticoagulation (High INR Management!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>INR 4.5 – 10, NO Bleeding:</b></mark> <mark class=\"hl rx\"><b>Hold Warfarin</b></mark> until INR returns to therapeutic range (routine Vitamin K NOT needed!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>INR &gt; 10, NO Bleeding:</b></mark> <mark class=\"hl rx\"><b>Hold Warfarin + Give Oral Vitamin K1 (2.5–5 mg)</b></mark> .</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>ANY Elevated INR + LIFE-THREATENING BLEEDING (ICH / GI Bleed):</b></mark> <mark class=\"hl rx\"><b>Hold Warfarin + IV Vitamin K 10 mg (slow over 30 min) PLUS 4-Factor PCC (Prothrombin Complex Concentrate)</b></mark> immediately (or FFP if PCC unavailable)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u377\">← Module 2</button><button class=\"nv\" data-u=\"u379\">Module 4 →</button></nav></article><article class=\"view unit\" id=\"u379\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 4</span><h1>Liver Function Tests (LFTs)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Liver+Function+Tests+%28LFTs%29+medical\">🔍 Search on Google</a></header><p><i>(Critical Pearl: </i><mark class=\"hl mech\"><i><b>ALT, AST, &amp; ALP measure Liver INJURY, NOT Liver Function!</b></i></mark><i> True </i><i><b>Synthetic Liver Function</b></i><i> is measured by </i><mark class=\"hl mech\"><i><b>Albumin, PT/INR, and Bilirubin clearance</b></i></mark><i> !)</i></p><h3><b>1. Hepatocellular vs. Cholestatic Injury Patterns (Separated!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Pattern</b></p></th><th><p><b>Primary Elevation</b></p></th><th><p><b>Separated Differential Diagnosis</b></p></th></tr><tr><td><p><b>Hepatocellular Pattern</b></p></td><td><p><mark class=\"hl mech\"><b>ALT</b></mark> <i>(Alanine Aminotransferase — more liver-specific!)</i> &amp; <mark class=\"hl mech\"><b>AST</b></mark> <i>(Aspartate Aminotransferase)</i> (Normal: ~10–40 U/L)</p></td><td><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>&gt; 1,000 U/L (\"Marked Transaminitis\" — ONLY 3 Main Causes!):</b> <b>Acute Viral Hepatitis (HAV/HBV)</b>, <mark class=\"hl mech\"><b>Ischemic Hepatitis (\"Shock Liver\" — LDH also &gt; 1,000!)</b></mark> , <b>Drug/Toxin Toxicity (Acetaminophen/Paracetamol overdose!)</b>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Mild-Moderate (&lt; 300–500 U/L):</b> <mark class=\"hl lab\"><b>MASLD/NAFLD (ALT &gt; AST)</b></mark> , Chronic HCV/HBV, Autoimmune Hepatitis, Wilson’s, Hemochromatosis, <b>Celiac Disease</b>, <b>Muscle Injury / Rhabdomyolysis</b> (check <b>CK</b> — AST &gt; ALT!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl mech\"><b>AST : ALT Ratio ≥ 2:1 (with AST &lt; 300):</b></mark> Classic for <b>Alcoholic Hepatitis</b> (pyridoxal-5-phosphate/B6 deficiency lowers ALT!) <b>OR Advanced Cirrhosis</b> (ratio flips from ALT&gt;AST to AST&gt;ALT)!</span></p></td></tr><tr><td><p><b>Cholestatic Pattern</b></p></td><td><p><mark class=\"hl mech\"><b>ALP</b></mark> <i>(Alkaline Phosphatase, 40–130 U/L) </i>&amp; <b>GGT</b> <i>(Gamma-Glutamyl Transferase)</i> &amp; <b>Direct Bilirubin</b></p></td><td><p><b>First Step — Check GGT (or 5’-Nucleotidase):</b></p>\n<p>• <mark class=\"hl mech\"><b>High ALP + High GGT = HEPATOBILIARY Source!</b></mark> -&gt; Do <b>Abdominal Ultrasound </b>immediately: <i>Dilated ducts</i> = <mark class=\"hl lab\"><b>CBD Stone, Pancreatic Cancer, Cholangiocarcinoma</b></mark> ; <i>Non-dilated ducts</i> = <mark class=\"hl lab\"><b>PBC (AMA+), PSC, Drug-induced cholestasis (Amoxicillin-Clavulanate/Steroids)</b></mark> , Sepsis!</p>\n<p>• <mark class=\"hl mech\"><b>High ALP + NORMAL GGT = BONE / PLACENTAL Source!</b></mark> -&gt; <mark class=\"hl lab\"><b>Pregnancy</b></mark> , Growing children, <b>Paget’s Disease of Bone</b>, <b>Rickets/Osteomalacia</b>, Bone Metastases, Healing fracture!</p></td></tr></table><h3><b>2. Bilirubin Differentiation (Total: 0.2–1.2 mg/dL | Direct: &lt; 0.3 mg/dL)</b></h3><ul>\n<li class=\"l1\"><b>Unconjugated (Indirect) Hyperbilirubinemia (&gt; 80–85% Indirect, NO Urine Bilirubin!):</b></li>\n<li class=\"l2\"><i>Causes:</i> <b>Hemolysis</b> (high LDH, high retics, low haptoglobin), <b>Gilbert’s Syndrome</b> (benign UGT defect — mild jaundice during fasting/illness/stress!), <b>Physiologic neonatal jaundice</b>, Resorption of large hematoma.</li>\n<li class=\"l1\"><b>Conjugated (Direct) Hyperbilirubinemia (&gt; 20–50% Direct, Dark Tea Urine [Urine Bilirubin +]!):</b></li>\n<li class=\"l2\"><i>Causes:</i> <b>Biliary Obstruction</b> (CBD stone, tumor), <b>Hepatocellular disease</b> (Viral hepatitis, Cirrhosis), <mark class=\"hl lab\"><b>Sepsis</b></mark> , <b>Dubin-Johnson / Rotor syndrome</b>, <b>Biliary Atresia </b>(neonates!).</li>\n</ul><h3><b>3. Synthetic Function Markers</b></h3><ul>\n<li class=\"l1\"><b>Serum Albumin (3.5–5.0 g/dL):</b> Half-life ~20 days (reflects <b>chronic</b> liver failure; also drops in <mark class=\"hl lab\"><b>Nephrotic Syndrome</b></mark> , Malnutrition, Protein-losing enteropathy, and Acute Inflammation/Sepsis as a negative acute-phase reactant!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>PT / INR:</b></mark> Half-life of Factor VII is ~6 hours -&gt; <b>BEST marker of ACUTE liver failure &amp; prognosis</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u378\">← Module 3</button><button class=\"nv\" data-u=\"u380\">Module 5 →</button></nav></article><article class=\"view unit\" id=\"u380\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 5</span><h1>Kidney Function Tests (KFTs) &amp; Urinalysis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Kidney+Function+Tests+%28KFTs%29+%26+Urinalysis+medical\">🔍 Search on Google</a></header><h3><b>1. Serum Creatinine, BUN &amp; eGFR</b></h3><ul>\n<li class=\"l1\"><b>Serum Creatinine (0.6–1.3 mg/dL):</b> Byproduct of muscle creatine breakdown; <b>DEPENDS ON MUSCLE MASS</b> (a Cr of 1.3 mg/dL in a frail 45-kg elderly woman may already represent <mark class=\"hl lab\"><b>CKD Stage 3b [eGFR &lt; 40]</b></mark> ; a Cr of 1.4 mg/dL in a muscular bodybuilder may be normal!). <b>Lag Trap:</b> Creatinine takes <b>24–48 hours</b> to rise after an acute kidney insult!</li>\n<li class=\"l1\"><b>BUN (Blood Urea Nitrogen, 7–20 mg/dL):</b> <i>Convert Egypt’s common </i><mark class=\"hl mech\"><i><b>Urea</b></i></mark><i> to BUN by dividing by </i><i><b>2.14</b></i><i> (BUN = Urea ÷ 2.14, so normal Urea ≈ 15–43 mg/dL)!</i></li>\n<li class=\"l2\"><i>Elevated BUN Out of Proportion to Creatinine (</i><i><b>BUN:Cr &gt; 20:1</b></i><i>):</i> <b>Prerenal Dehydration/CHF</b>, <b>Upper GI Bleed</b> (blood protein digested in gut!), <b>High-Protein Diet / Catabolism</b>, <mark class=\"hl rx\"><b>Corticosteroids / Tetracyclines</b></mark> !</li>\n<li class=\"l2\"><i>Low BUN:</i> <b>Liver Failure</b> (impaired urea cycle!), Malnutrition, <b>SIADH</b>!</li>\n<li class=\"l1\"><b>UACR</b> <i>(Urine Albumin-to-Creatinine Ratio, Normal &lt; 30 mg/g)</i>: <b>Earliest screening test for Diabetic Nephropathy</b> (30–300 mg/g = Moderately increased [microalbuminuria]; &gt; 300 mg/g = Severely increased!).</li>\n</ul><h3><b>2. Urinalysis &amp; Microscopy Pearls (The Liquid Kidney Biopsy!)</b></h3><ul>\n<li class=\"l1\"><b>Dipstick Blood (+) vs. Microscopy:</b></li>\n<li class=\"l2\"><i>Dipstick Blood (+) WITH RBCs on microscopy:</i> <b>True Hematuria</b> (Stone, Tumor, UTI, GN).</li>\n<li class=\"l2\"><i>Dipstick Blood (+) WITH </i><i><b>ZERO RBCs</b></i><i> on microscopy:</i> <b>Rhabdomyolysis (Myoglobinuria)</b> OR <b>Intravascular Hemolysis (Hemoglobinuria — e.g., G6PD Favism!)</b>!</li>\n<li class=\"l1\"><b>Nitrites (+) + Leukocyte Esterase (+):</b> Bacterial <b>UTI</b> (Nitrites = Enterobacteriaceae like <i>E. coli</i> converting nitrate; <i>Enterococcus</i> &amp; <i>Staph</i> are Nitrite-negative!). <mark class=\"hl mech\"><b>Sterile Pyuria (WBCs without bacteria on routine culture):</b></mark> Rule out <b>Renal TB</b> (classic!), Nephrolithiasis, <b>AIN</b> (eosinophiluria), Urethritis (<i>Chlamydia</i>), Appendicitis/PID adjacent to ureter!</li>\n<li class=\"l1\"><b>Urine Casts (Pathognomonic!):</b></li>\n<li class=\"l2\"><b>RBC Casts (+ Dysmorphic RBCs):</b> <b>Glomerulonephritis</b> (PSGN, Lupus, IgA, ANCA!).</li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>WBC Casts:</b></mark> <b>Acute Pyelonephritis</b> or <b>Acute Interstitial Nephritis (AIN)</b>!</li>\n<li class=\"l2\"><b>\"Muddy Brown\" Granular Casts:</b> <b>Acute Tubular Necrosis (ATN)</b>!</li>\n<li class=\"l2\"><b>Fatty Casts (\"Maltese Cross\"):</b> <b>Nephrotic Syndrome</b>!</li>\n<li class=\"l2\"><b>Broad Waxy Casts:</b> <mark class=\"hl lab\"><b>End-Stage CKD</b></mark> !</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u379\">← Module 4</button><button class=\"nv\" data-u=\"u381\">Module 6 →</button></nav></article><article class=\"view unit\" id=\"u381\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 6</span><h1>Serum Electrolytes &amp; Minerals</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Serum+Electrolytes+%26+Minerals+medical\">🔍 Search on Google</a></header><table class=\"t wide\"><tr class=\"hd\"><th><p><b>Electrolyte</b></p></th><th><p><b>Normal Range</b></p></th><th><p><b>Key Hypo- Causes (Separated)</b></p></th><th><p><b>Key Hyper- Causes (Separated)</b></p></th><th><p><mark class=\"hl mech\"><b>Critical Action / ECG Clue</b></mark></p></th></tr><tr><td><p><b>Sodium (Na+)</b></p></td><td><p>135 – 145 mEq/L</p></td><td><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i>Check Osmolality FIRST!</i> (True Hypo-osmolar &lt; 275 vs. Hyperglycemia/Lipids).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>Hypovolemic:</i> Vomiting, diarrhea,</span></p></td><td><p><b>Net Water Loss (Dehydration):</b> Impaired thirst/elderly, Diabetes Insipidus, Osmotic diuresis (HHS), Fever/burns.</p></td><td><p><b>NEVER correct chronic Na+ faster than 6–8 mEq/L per 24 hrs</b> (Hypo -&gt; <b>ODS</b>; Hyper -&gt; <b>Cerebral Edema</b>)!</p></td></tr><tr><td></td><td></td><td><p><b>Thiazides</b>.</p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i>Euvolemic:</i> <b>SIADH</b>, Hypothyroidism, Beer potomania.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><i>Hypervolemic:</i> <b>CHF, Cirrhosis, Nephrotic</b>.</span></p></td><td></td><td></td></tr><tr><td><p><b>Potassium (K+)</b></p></td><td><p>3.5 – 5.0 mEq/L</p></td><td><p><b>Loop/Thiazide diuretics</b>, Vomiting/NG suction, Diarrhea, <mark class=\"hl rx\"><b>Insulin/β2-agonists</b></mark> , <b>Hypomagnesemia</b> (<i>always fix Mg++ or K+ won't stay up!</i>), Conn’s.</p></td><td><p><mark class=\"hl lab\"><b>AKI/CKD</b></mark> , Drugs (<mark class=\"hl rx\"><b> ACE-i/ARB, Spironolactone, NSAIDs, TMP-SMX</b></mark> ), <mark class=\"hl lab\"><b>DKA/Acidosis</b></mark> , Rhabdomyolysis, <b>Hemolyzed blood draw </b>(<i>pseudohyperkalemia</i>!).</p></td><td><p><i>HypoK+ ECG:</i> <b>Flat T, U waves, ST depression</b>.</p>\n<p><i>HyperK+ ECG:</i> <b>Peaked T -&gt; Flat P -&gt; Wide QRS -&gt; Sine wave</b> (<mark class=\"hl rx\"><b> IV Calcium Gluconate STAT!</b></mark> ).</p></td></tr><tr><td><p><b>Calcium (Ca++)</b></p></td><td><p>8.5 – 10.5 mg/dL <i>(Ionized: 4.5– 5.3)</i></p></td><td><p><b>Always Correct for Albumin:</b> Corrected Ca = Measured Ca + 0.8 × (4.0 − Albumin)!</p>\n<p>Causes: <b>Post-thyroidectomy Hypoparathyroidism</b>, <b>Vit D deficiency</b>, <mark class=\"hl lab\"><b>CKD</b></mark> , <b>Acute Pancreatitis</b>, <b>Hypomagnesemia</b>, Massive citrate transfusion.</p></td><td><p><b>Primary Hyperparathyroidism </b>(outpatient #1) &amp; <b>Malignancy</b> (inpatient #1), Vit D toxicity, Sarcoidosis, Thiazides.</p></td><td><p><i>HypoCa++:</i> <b>Chvostek/Trousseau, Tetany, Prolonged QTc</b> -&gt; <mark class=\"hl rx\"><b>IV Calcium Gluconate</b></mark> !</p>\n<p><i>HyperCa++:</i> <b>Short QTc</b> -&gt; <b>IV Normal Saline + Calcitonin + Zoledronic acid</b>!</p></td></tr><tr><td><p><b>Magnesium (Mg++)</b></p></td><td><p>1.7 – 2.2 mg/dL</p></td><td><p>Diarrhea/malabsorption, <b>Alcoholism</b>, <mark class=\"hl rx\"><b>PPIs</b></mark> (chronic!), Loop/thiazide diuretics, Cisplatin/Amphotericin.</p></td><td><p><mark class=\"hl lab\"><b>CKD + Mg-laxatives/antacids</b></mark> , <b>IV MgSO4 overdose</b> (loss of patellar reflexes!).</p></td><td><p><i>HypoMg++:</i> Refractory HypoK+/HypoCa++ &amp; <b>Torsades de Pointes</b> (<b>IV MgSO4 2 g!</b>).</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u380\">← Module 5</button><button class=\"nv\" data-u=\"u382\">Module 7 →</button></nav></article><article class=\"view unit\" id=\"u382\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 7</span><h1>Cardiac &amp; Endocrine Biomarkers</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiac+%26+Endocrine+Biomarkers+medical\">🔍 Search on Google</a></header><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl mech\"><b>High-Sensitivity Cardiac Troponin (hs-cTn):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl mech\"><b>Gold standard for Myocardial Necrosis (MI)</b></mark> — rises within <b>1–3 hours</b>, peaks 12–24 hrs, stays elevated <b>7–14 days</b> (so use <b>CK-MB</b> or serial troponin spikes if diagnosing <i>early re-infarction</i>!).</li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>CRITICAL TRAP — Non-ACS Causes of Elevated Troponin (\"Demand Ischemia / Type 2 MI / Myocardial Injury\"):</b></mark> <mark class=\"hl lab\"><b>Sepsis</b></mark> , <mark class=\"hl lab\"><b>Pulmonary Embolism (RV strain)</b></mark> , <b>Acute Heart Failure</b>, <mark class=\"hl lab\"><b>Renal Failure (CKD — chronic stable elevation!)</b></mark> , <b>Myocarditis</b>, <mark class=\"hl lab\"><b>Aortic Dissection</b></mark> , <mark class=\"hl lab\"><b>Severe Tachyarrhythmia (AFib RVR)</b></mark> ! <i>Look for a </i><mark class=\"hl lab\"><i><b>RISE and/or FALL</b></i></mark><i> + ischemic symptoms/ECG changes to diagnose Acute MI!</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>BNP (&lt; 100 pg/mL) / NT-proBNP (&lt; 300 pg/mL):</b></span></p>\n<ul>\n<li class=\"l2\"><b>High Negative Predictive Value:</b> Normal BNP virtually <mark class=\"hl dx\"><b>RULES OUT Acute Heart Failure</b></mark> as the cause of acute dyspnea!</li>\n<li class=\"l2\"><i>Traps:</i> <b>Falsely LOW in Obesity</b>; <mark class=\"hl lab\"><b>Falsely HIGH in CKD, Elderly, AFib, Sepsis, &amp; PE</b></mark> !</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl mech\"><b>HbA1c (Normal &lt; 5.7% | Prediabetes 5.7–6.4% | Diabetes ≥ 6.5%):</b></mark></span></p>\n<ul>\n<li class=\"l2\">Reflects mean blood glucose over <b>2–3 months</b> (120-day RBC lifespan).</li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>TRAPS WHERE HbA1c IS UNRELIABLE (Use Fasting Glucose / Fructosamine instead!):</b></mark> <b>Hemolytic Anemia / Thalassemia / Sickle Cell / Recent Blood Transfusion</b> (falsely LOW!), <mark class=\"hl lab\"><b>Iron Deficiency Anemia</b></mark> (falsely HIGH!), <mark class=\"hl lab\"><b>CKD / Erythropoietin</b></mark> , <mark class=\"hl lab\"><b>Pregnancy</b></mark> !</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><mark class=\"hl mech\"><b>Thyroid Panel (TSH + Free T4 + Free T3):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl mech\"><b>TSH is the BEST initial screen!</b></mark></li>\n<li class=\"l2\"><i>Low TSH + High FT4/FT3:</i> <mark class=\"hl lab\"><b>Primary Hyperthyroidism</b></mark> (Graves’/Toxic MNG).</li>\n<li class=\"l2\"><i>Low TSH + Normal FT4:</i> Check <mark class=\"hl mech\"><b>Free T3</b></mark> (<i>T3-toxicosis</i>) vs. <i>Subclinical Hyperthyroidism</i>.</li>\n<li class=\"l2\"><i>High TSH + Low FT4:</i> <mark class=\"hl lab\"><b>Primary Hypothyroidism</b></mark> (Hashimoto’s).</li>\n<li class=\"l2\"><i>High TSH + Normal FT4:</i> <i>Subclinical Hypothyroidism</i>.</li>\n<li class=\"l2\"><i>Low/Normal TSH + Low FT4:</i> <mark class=\"hl lab\"><b>Central (Pituitary) Hypothyroidism</b></mark> OR <b>Sick Euthyroid Syndrome</b> (non-thyroidal illness in ICU sepsis — <i>do NOT treat ICU patients with levothyroxine unless true hypothyroidism proven!</i>).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u381\">← Module 6</button><button class=\"nv\" data-u=\"u383\">Module 8 →</button></nav></article><article class=\"view unit\" id=\"u383\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 8</span><h1>Autoimmune &amp; Serology Quick Reference</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Autoimmune+%26+Serology+Quick+Reference+medical\">🔍 Search on Google</a></header><table class=\"t \"><tr class=\"hd\"><th><p><mark class=\"hl lab\"><b>Test</b></mark></p></th><th><p><b>Primary Disease Association &amp; Clinical Pearl</b></p></th></tr><tr><td><p><mark class=\"hl mech\"><b>ANA</b></mark> <i>(Antinuclear Antibody)</i></p></td><td><p><mark class=\"hl lab\"><b>Best SCREENING test for SLE (~98% sensitive)</b></mark> — <i>Low specificity!</i> Can be positive at low titers (1:40–1:80) in ~15% of healthy individuals, infection, or aging!</p></td></tr><tr><td><p><b>Anti-dsDNA &amp; Anti-Smith</b></p></td><td><p><mark class=\"hl lab\"><b>HIGHLY SPECIFIC for SLE!</b></mark> (<i>Anti-dsDNA titers correlate with </i><i><b>Lupus Nephritis</b></i><i> activity!</i>)</p></td></tr><tr><td><p><b>Anti-Histone</b></p></td><td><p><b>Drug-Induced Lupus</b> (<mark class=\"hl rx\"><b> Hydralazine, Procainamide, Isoniazid, Minocycline, Anti-TNF</b></mark> — spares CNS/kidneys!).</p></td></tr><tr><td><p><b>Anti-Ro (SSA) &amp; Anti-La (SSB)</b></p></td><td><p><b>Sjögren’s Syndrome</b> + <b>Neonatal Lupus / Congenital Heart Block</b>!</p></td></tr><tr><td><p><b>RF</b> <i>(Rheumatoid Factor)</i> &amp; <b>Anti-CCP</b></p></td><td><p><mark class=\"hl lab\"><b>Rheumatoid Arthritis:</b></mark> <b>Anti-CCP is 95–98% SPECIFIC</b>; RF is non-specific (often positive in <b>HCV Cryoglobulinemia</b>, Endocarditis, Sjögren’s!).</p></td></tr><tr><td><p><mark class=\"hl mech\"><b>c-ANCA (PR3)</b></mark> vs. <mark class=\"hl mech\"><b>p-ANCA (MPO)</b></mark></p></td><td><p><mark class=\"hl mech\"><b>c-ANCA:</b></mark> <b>GPA (Wegener’s)</b> | <mark class=\"hl mech\"><b>p-ANCA:</b></mark> <b>MPA</b>, <b>EGPA (Churg-Strauss)</b>, Ulcerative Colitis.</p></td></tr><tr><td><p><b>Low C3 / C4 Complement</b></p></td><td><p>Active <mark class=\"hl lab\"><b>SLE flare / Lupus Nephritis</b></mark> , <mark class=\"hl lab\"><b>PSGN</b></mark> (Low C3, normalizes in 6–8 wks!), <b>MPGN</b>, <b>Cryoglobulinemia (HCV)</b>.</p></td></tr><tr><td><p><b>ASOT</b> <i>(Anti-Streptolysin O Titer)</i></p></td><td><p>Proves <b>recent GAS infection</b> for <b>Acute Rheumatic Fever</b> or <mark class=\"hl lab\"><b>PSGN</b></mark> (<i>NOT a test for chronic rheumatic heart disease or active strep throat!</i>).</p></td></tr></table><p class=\"muted\"><i>End of Part 15A — Essential Laboratory Interpretation Mastery Complete!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u382\">← Module 7</button><button class=\"nv\" data-u=\"u384\">Overview →</button></nav></article><article class=\"view unit\" id=\"u384\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Overview</span><h1>Crucial &amp; Potentially Fatal Drug Interactions</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Crucial+%26+Potentially+Fatal+Drug+Interactions+medical\">🔍 Search on Google</a></header><h4><i><b>A Physician’s Prescribing Safety Encyclopedia</b></i></h4><nav class=\"un\"><button class=\"nv\" data-u=\"u383\">← Module 8</button><button class=\"nv\" data-u=\"u385\">Module 1 →</button></nav></article><article class=\"view unit\" id=\"u385\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 1</span><h1>Cardiovascular &amp; Antithrombotic Interactions</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cardiovascular+%26+Antithrombotic+Interactions+medical\">🔍 Search on Google</a></header><h3><b>1. Nitrates + PDE-5 Inhibitors (</b><b>FATAL HYPOTENSIVE SHOCK!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Interacting Drugs:</b> <mark class=\"hl rx\"><b>Nitroglycerin / Isosorbide Dinitrate / Mononitrate</b></mark> + <b>Sildenafil, Tadalafil, Vardenafil, Avanafil</b> (or <b>Riociguat</b>).</li>\n<li class=\"l1\"><b>Mechanism:</b> Nitrates supply Nitric Oxide (raising <b>cGMP</b> [Cyclic Guanosine Monophosphate]), while <b>PDE-5</b> (Phosphodiesterase-5) inhibitors block cGMP breakdown -&gt; synergistic, massive systemic vasodilation.</li>\n<li class=\"l1\"><b>Clinical Consequence:</b> <b>Refractory, life-threatening Hypotension, Shock, and Acute Myocardial Infarction (MI)!</b></li>\n<li class=\"l1\"><b>Safe Clinical Rule:</b> <b>STRICTLY CONTRAINDICATED!</b> Wait <b>≥ 24 hours</b> after Sildenafil/Vardenafil and <b>≥ 48 hours</b> after Tadalafil before administering ANY nitrate! <i>(Ask EVERY chest-pain patient in the ER about sexual-enhancement pills before giving Nitroglycerin!)</i></li>\n</ul><h3><b>2. Warfarin Interactions (</b><b>Narrow Therapeutic Index — High Hemorrhage or Clot Risk!</b><b>)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Potentiators (INCREASE INR -&gt; Major Bleeding / ICH</b></mark> [Intracranial Hemorrhage] <b>Risk!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Antibiotics (Huge Daily Trap in Egypt!):</b> <mark class=\"hl rx\"><b>Metronidazole</b></mark> , <b>TMP-SMX</b> (Trimethoprim-Sulfamethoxazole / Septrin), <mark class=\"hl rx\"><b>Fluoroquinolones (Ciprofloxacin/Levofloxacin)</b></mark> , <mark class=\"hl rx\"><b>Macrolides (Erythromycin/Clarithromycin — </b></mark><i><b>Azithromycin is safer!</b></i><mark class=\"hl rx\"><b>)</b></mark> , <mark class=\"hl rx\"><b>Fluconazole</b></mark> — both inhibit <b>CYP2C9/3A4</b> metabolism AND eradicate Vitamin K-producing gut flora!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Cardiac / Other:</b> <mark class=\"hl rx\"><b>Amiodarone</b></mark> (potent CYP inhibitor -&gt; must <mark class=\"hl rx\"><b>reduce Warfarin dose by 30–50%</b></mark> when starting Amiodarone!), <mark class=\"hl rx\"><b>NSAIDs / Aspirin</b></mark> (antiplatelet + GI mucosal injury -&gt; catastrophic GI bleed!), <b>Acetaminophen</b> (high chronic doses &gt; 2–3 g/day ), <mark class=\"hl rx\"><b>Omeprazole/Cimetidine</b></mark> .</span></p>\n<ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Antagonists (DECREASE INR -&gt; Fatal Thrombosis / Valve Clot / Stroke Risk!):</b></mark></li>\n<li class=\"l2\"><b>Rifampin</b>, <b>Carbamazepine</b>, <b>Phenytoin</b>, <b>Phenobarbital</b>, <b>St. John’s Wort</b> (potent CYP450 inducers!), and sudden surges in <b>Vitamin K-rich green leafy vegetables</b> (spinach, molokhia, kale — advise <i>consistent</i> intake, not complete avoidance!).</li>\n</ul><h3><b>3. Clopidogrel + PPIs (</b><b>Reduced Antiplatelet Activation</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Clopidogrel is a prodrug requiring <b>CYP2C19</b> activation in the liver; <mark class=\"hl rx\"><b>Omeprazole</b></mark> &amp; <mark class=\"hl rx\"><b>Esomeprazole</b></mark> strongly inhibit CYP2C19!</li>\n<li class=\"l1\"><b>Safe Rule:</b> When GI protection is needed with Clopidogrel, prescribe <mark class=\"hl rx\"><b>Pantoprazole</b></mark> (or Rabeprazole/Famotidine), NOT Omeprazole/Esomeprazole!</li>\n</ul><h3><b>4. Beta-Blockers + Non-Dihydropyridine CCBs (</b><b>AV Block / Asystole!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Interacting Drugs:</b> <b>Beta-blockers</b> (Bisoprolol, Metoprolol, Propranolol, Atenolol) + <mark class=\"hl rx\"><b>Verapamil or Diltiazem</b></mark> (<b>CCBs</b> [Calcium Channel Blockers]).</li>\n<li class=\"l1\"><b>Mechanism:</b> Additive negative chronotropic and dromotropic depression of the <b>SA</b> (Sinoatrial) and <b>AV</b> (Atrioventricular) nodes + negative inotropy.</li>\n<li class=\"l1\"><b>Consequence:</b> <b>Severe Bradycardia, High-Degree AV Block, Cardiogenic Shock, or Asystole</b>!</li>\n<li class=\"l1\"><b>Safe Rule:</b> <mark class=\"hl rx\"><b>NEVER combine Oral/IV Beta-blockers with Verapamil or Diltiazem!</b></mark> <i>(Dihydropyridine CCBs like </i><mark class=\"hl rx\"><i><b>Amlodipine / Nifedipine</b></i></mark><i> ARE safe to combine with Beta-blockers!)</i></li>\n</ul><h3><b>5. Digoxin Interactions (</b><b>Narrow Therapeutic Index: 0.5–0.9 ng/mL in HF!</b><b>)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Drugs Raising Digoxin Levels (Toxic Accumulation!):</b></mark> <mark class=\"hl rx\"><b>Amiodarone</b></mark> (halve Digoxin dose!), <mark class=\"hl rx\"><b>Verapamil</b></mark> , <mark class=\"hl rx\"><b>Macrolides (Clarithromycin/Erythromycin)</b></mark> , <mark class=\"hl rx\"><b>Spironolactone</b></mark> , <b>Quinidine</b>.</li>\n<li class=\"l1\"><b>Drugs Precipitating Toxicity at Normal Levels:</b> <b>Loop &amp; Thiazide Diuretics</b> (<b>Hypokalemia &amp; Hypomagnesemia</b> sensitize Na+/K+-ATPase to Digoxin -&gt; fatal arrhythmias!).</li>\n<li class=\"l1\"><b>Toxicity Clues:</b> Nausea/anorexia, <b>yellow-green visual halos (xanthopsia)</b>, <b>Bidirectional VT</b> or <b>Atrial Tachycardia with Block</b> -&gt; Treat severe toxicity with <mark class=\"hl rx\"><b>Digoxin Immune Fab (Digibind)</b></mark> + correct K+/Mg++!</li>\n</ul><h3><b>6. ACE-Inhibitors + Sacubitril/Valsartan (ARNI) (</b><b>Angioedema Risk!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Both inhibit bradykinin breakdown (ACE-i blocks ACE; Sacubitril blocks neprilysin).</li>\n<li class=\"l1\"><b>Mandatory Rule:</b> Allow a strict <b>36-HOUR WASHOUT PERIOD</b> after stopping an ACE-i (e.g., Ramipril/Enalapril) BEFORE starting Sacubitril/Valsartan (<b>NO washout needed</b> when switching from an <mark class=\"hl rx\"><b>ARB</b></mark> like Valsartan!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u384\">← Overview</button><button class=\"nv\" data-u=\"u386\">Module 2 →</button></nav></article><article class=\"view unit\" id=\"u386\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 2</span><h1>Renal, Electrolyte &amp; Immunosuppressant Interactions</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Renal%2C+Electrolyte+%26+Immunosuppressant+Interactions+medical\">🔍 Search on Google</a></header><h3><b>1. The \"Triple Whammy\" (</b><b>Acute Kidney Injury Cocktail!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Interacting Drugs:</b> <mark class=\"hl rx\"><b>ACE-Inhibitor (or ARB)</b></mark> <b>PLUS</b> <b>Diuretic (Loop/Thiazide)</b> <b>PLUS</b> <mark class=\"hl rx\"><b>NSAID</b></mark> (e.g., Diclofenac, Ibuprofen, Ketorolac)!</li>\n<li class=\"l1\"><b>Mechanism (Separated):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Diuretic reduces intravascular volume (renal perfusion drops).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl rx\"><b>NSAID</b></mark> constricts the <b>Afferent</b> glomerular arteriole (blocks prostaglandins).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl rx\"><b>ACE-i/ARB</b></mark> dilates the <b>Efferent</b> glomerular arteriole (blocks Angiotensin II).</span></p>\n<ul>\n<li class=\"l1\"><b>Consequence:</b> Glomerular filtration pressure collapses -&gt; <mark class=\"hl lab\"><b>Severe Prerenal AKI / ATN!</b></mark> <i>(Avoid NSAIDs in patients taking ACE-i/ARBs + diuretics!)</i></li>\n</ul><h3><b>2. Fatal Hyperkalemia Combinations</b></h3><ul>\n<li class=\"l1\"><b>Interacting Drugs:</b> Combining <b>≥ 2</b> of: <mark class=\"hl rx\"><b>ACE-i / ARB</b></mark> , <mark class=\"hl rx\"><b>Spironolactone / Eplerenone</b></mark> , <b>TMP-SMX</b> (Trimethoprim blocks ENaC channels in collecting duct like Amiloride!), <mark class=\"hl rx\"><b>NSAIDs</b></mark> , <b>Potassium supplements</b>, <mark class=\"hl rx\"><b>Heparin</b></mark> , <mark class=\"hl rx\"><b>Tacrolimus/Cyclosporine</b></mark> (especially in <mark class=\"hl lab\"><b>CKD</b></mark> or elderly!).</li>\n<li class=\"l1\"><b>Consequence:</b> <b>Life-Threatening Hyperkalemia (Peaked T waves -&gt; Sine Wave -&gt; VF/Asystole!)</b>!</li>\n</ul><h3><b>3. Lithium Toxicity Interactions (</b><b>Therapeutic Window: 0.6–1.2 mEq/L!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Drugs Raising Lithium Levels (&gt; 1.5–2.0 mEq/L):</b> <mark class=\"hl rx\"><b>NSAIDs</b></mark> (all except Aspirin/Sulindac slightly safer), <b>Thiazide Diuretics</b> (HCTZ/Chlorthalidone — <i>#1 trigger! </i>Proximal Na+ depletion forces compensatory Na+ &amp; Lithium reabsorption!), <mark class=\"hl rx\"><b>ACE-i / ARBs</b></mark> , <mark class=\"hl rx\"><b>Metronidazole</b></mark> , <b>Dehydration</b>!</li>\n<li class=\"l1\"><b>Consequence:</b> Coarse tremor, ataxia, dysarthria, <b>Nephrogenic Diabetes Insipidus</b>, seizures, coma!</li>\n</ul><h3><b>4. Methotrexate + NSAIDs / TMP-SMX / Penicillins (</b><b>Fatal Pancytopenia!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> <mark class=\"hl rx\"><b>NSAIDs</b></mark> and <b>Penicillins/Probenecid</b> block renal tubular secretion of Methotrexate; <b>TMP-SMX</b> adds synergistic <b>folate antagonism</b>!</li>\n<li class=\"l1\"><b>Consequence:</b> <mark class=\"hl lab\"><b>Severe Bone Marrow Suppression (Pancytopenia), Mucositis, Hepatotoxicity, &amp; AKI!</b></mark> <i>(Note: High-dose </i><i><b>daily</b></i><i> Methotrexate accidental ingestion instead of </i><i><b>ONCE WEEKLY</b></i><i> dosing is also a classic fatal prescription error!)</i></li>\n</ul><h3><b>5. Allopurinol + Azathioprine (or 6-Mercaptopurine) (</b><b>Fatal Myelotoxicity!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Azathioprine is converted to 6-MP, which is inactivated by <b>Xanthine Oxidase</b>; <mark class=\"hl rx\"><b>Allopurinol</b></mark> (and Febuxostat!) inhibits Xanthine Oxidase -&gt; 4–5× spike in active toxic 6-MP!</li>\n<li class=\"l1\"><b>Consequence:</b> <b>Profound, Fatal Agranulocytosis / Pancytopenia!</b> -&gt; <b>AVOID combination</b> (or reduce Azathioprine dose by 75% under strict specialist monitoring!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u385\">← Module 1</button><button class=\"nv\" data-u=\"u387\">Module 3 →</button></nav></article><article class=\"view unit\" id=\"u387\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 3</span><h1>Qtc Prolongation &amp; Torsades DE Pointes Combinations</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Qtc+Prolongation+%26+Torsades+DE+Pointes+Combinations+medical\">🔍 Search on Google</a></header><h3><b>1. Mechanism &amp; Danger</b></h3><p>Blockade of cardiac <b>hERG Potassium channels</b> delays ventricular repolarization (<b>QTc &gt; 500 ms</b>), triggering early afterdepolarizations -&gt; <b>Torsades de Pointes </b>(Polymorphic VT) -&gt; <b>Sudden Cardiac Death</b>!</p><h3><b>2. High-Risk Drug Combos (Mnemonic: \"ABCDE\" QT Drugs — Never Stack ≥ 2 Without ECG Monitoring!)</b></h3><ul>\n<li class=\"l1\"><b>A</b>ntiarrhythmics: <mark class=\"hl rx\"><b>Amiodarone, Sotalol, Procainamide, Quinidine, Dofetilide</b></mark> .</li>\n<li class=\"l1\"><b>A</b>ntibiotics / <b>A</b>ntifungals: <b>Macrolides</b> (<mark class=\"hl rx\"><b> Clarithromycin, Erythromycin</b></mark> &gt; Azithromycin), <b>Fluoroquinolones</b> (<mark class=\"hl rx\"><b> Moxifloxacin &gt; Levofloxacin/Ciprofloxacin</b></mark> ), <b>Azoles</b></li>\n</ul>\n<p>(<mark class=\"hl rx\"><b> Fluconazole, Voriconazole</b></mark> ).</p>\n<ul>\n<li class=\"l1\"><b>A</b>ntiemetics: <b>Ondansetron</b> (high IV doses), <b>Domperidone</b> (restricted!), <b>Metoclopramide</b>.</li>\n<li class=\"l1\"><b>A</b>ntipsychotics &amp; <b>A</b>ntidepressants: <b>Haloperidol</b> (especially IV!), <b>Chlorpromazine, Quetiapine, Ziprasidone, Risperidone</b>; <b>TCAs</b> (Amitriptyline), <b>Citalopram (&gt; 40 mg/day) / Escitalopram</b>, <b>Trazodone</b>!</li>\n<li class=\"l1\"><b>O</b>thers: <b>Methadone</b>, <mark class=\"hl rx\"><b>Hydroxychloroquine</b></mark> , <b>Loperamide</b> (high abuse doses)!</li>\n<li class=\"l1\"><b>Amplifier:</b> <b>Hypokalemia &amp; Hypomagnesemia</b> (from Loop/Thiazide diuretics) dramatically multiply Torsades risk!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u386\">← Module 2</button><button class=\"nv\" data-u=\"u388\">Module 4 →</button></nav></article><article class=\"view unit\" id=\"u388\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 4</span><h1>CNS, Psychiatric, Antimicrobial &amp; Pain Interactions</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=CNS%2C+Psychiatric%2C+Antimicrobial+%26+Pain+Interactions+medical\">🔍 Search on Google</a></header><h3><b>1. Serotonin Syndrome Combos (</b><b>Rapid Neuromuscular &amp; Autonomic Storm!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Interacting Drugs:</b> Combining <b>≥ 2 Serotonergic Agents:</b></li>\n<li class=\"l2\"><b>SSRIs / SNRIs</b> (Fluoxetine, Sertraline, Venlafaxine, Duloxetine) <b>PLUS</b></li>\n<li class=\"l2\"><b>Tramadol</b> (<i>Huge daily risk in Egypt!</i>), <b>Linezolid</b> (antibiotic with <b>MAOI</b> activity!), <b>MAOIs</b> (Phenelzine, Selegiline — allow <b>14-day washout</b>, or <b>5 weeks after Fluoxetine</b>!), <b>Triptans</b> (Sumatriptan), <b>Dextromethorphan</b> (cough syrups!), <b>Ondansetron</b>, <b>Meperidine</b>, <b>St. John’s Wort</b>, <b>Methylene Blue</b>!</li>\n<li class=\"l1\"><b>Signs:</b> Agitation, hyperthermia, tachycardia, diaphoresis, <b>CLONUS + HYPERREFLEXIA</b>!</li>\n</ul><h3><b>2. Opioid + Benzodiazepine + Gabapentinoid (</b><b>\"Holy Trinity\" Respiratory Arrest!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Synergistic <b>GABAergic + Mu-opioid suppression</b> of medullary brainstem respiratory drive!</li>\n<li class=\"l1\"><b>Consequence:</b> <b>Profound Hypoventilation, Coma, &amp; Fatal Overdose!</b> (FDA Black-Box Warning — avoid co-prescribing!).</li>\n</ul><h3><b>3. MAOIs + Tyramine Foods or Sympathomimetics (</b><b>Hypertensive Crisis!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Non-selective <b>MAOIs</b> (Phenelzine, Tranylcypromine) prevent gut breakdown of dietary <b>Tyramine</b> (<b>aged cheeses, cured meats, soy sauce, fermented foods, draft beer</b>) -&gt; massive Norepinephrine surge! Same with <b>Pseudoephedrine / Phenylephrine / Ephedrine</b>!</li>\n<li class=\"l1\"><b>Consequence:</b> <b>Hypertensive Emergency (BP &gt; 200/120), Intracerebral Hemorrhage!</b></li>\n</ul><h3><b>4. Valproate + Lamotrigine (</b><b>Stevens-Johnson Syndrome / TEN Risk!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Valproate <b>doubles serum Lamotrigine levels</b> by inhibiting glucuronidation!</li>\n<li class=\"l1\"><b>Rule:</b> When adding Lamotrigine to Valproate, <b>START AT HALF THE NORMAL DOSE AND TITRATE ULTRA-SLOWLY</b> to prevent fatal <mark class=\"hl lab\"><b>SJS / TEN</b></mark> !</li>\n</ul><h3><b>5. Valproate + Carbapenems (Meropenem / Ertapenem / Imipenem) (</b><b>Breakthrough Status Epilepticus!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Carbapenems rapidly deplete serum Valproate levels by <b>&gt; 60–90% within 24–48 hours</b>!</li>\n<li class=\"l1\"><b>Rule:</b> <mark class=\"hl rx\"><b>NEVER use Meropenem/Ertapenem in an epileptic patient maintained on Valproate</b></mark> — switch antibiotic or add another antiseizure drug immediately!</li>\n</ul><h3><b>6. Disulfiram-Like Reaction (</b><b>Severe Flushing, Vomiting &amp; Hypotension!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Interacting Drugs:</b> <mark class=\"hl rx\"><b>Metronidazole</b></mark> (or Tinidazole, Cefotetan/Cefoperazone, Chlorpropamide) <b>+ Alcohol</b> (including alcohol-containing syrups/mouthwashes)!</li>\n<li class=\"l1\"><b>Rule:</b> Counsel patient to avoid alcohol during and for <b>48–72 hours after</b> finishing Metronidazole!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u387\">← Module 3</button><button class=\"nv\" data-u=\"u389\">Module 5 →</button></nav></article><article class=\"view unit\" id=\"u389\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 5</span><h1>Statins, Fluoroquinolones, Chelation &amp; Oral Contraceptive Traps</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Statins%2C+Fluoroquinolones%2C+Chelation+%26+Oral+Contraceptive+Traps+medical\">🔍 Search on Google</a></header><h3><b>1. Statin Rhabdomyolysis Interactions</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Highest-Risk Statins (Metabolized by CYP3A4):</b></mark> <mark class=\"hl rx\"><b>Simvastatin &amp; Atorvastatin</b></mark> (Lovastatin). <i>(Safest / Non-CYP3A4 Statins = </i><mark class=\"hl rx\"><i><b>Rosuvastatin &amp; Pravastatin</b></i></mark><i> !)</i></li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Dangerous Inhibitors Raising Statin Levels (Myopathy / Rhabdomyolysis / AKI!):</b></mark></li>\n<li class=\"l2\"><b>Gemfibrozil</b> (<mark class=\"hl rx\"><b> NEVER combine Gemfibrozil with ANY Statin!</b></mark> If fibrate needed, use <b>Fenofibrate</b>!).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Macrolides (Clarithromycin / Erythromycin — </b></mark><i><b>use Azithromycin instead!</b></i><mark class=\"hl rx\"><b>)</b></mark> .</li>\n<li class=\"l2\"><b>Azole Antifungals (Itraconazole/Ketoconazole)</b>, <mark class=\"hl rx\"><b>Cyclosporine</b></mark> , <mark class=\"hl rx\"><b>Amiodarone</b></mark> (limit Simvastatin ≤ 20 mg!), <mark class=\"hl rx\"><b>Diltiazem/Verapamil</b></mark> , <b>Grapefruit Juice</b> (&gt; 1 L/day)!</li>\n</ul><h3><b>2. Fluoroquinolones + Corticosteroids (</b><b>Achilles Tendon Rupture!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Interacting Drugs:</b> <mark class=\"hl rx\"><b>Ciprofloxacin / Levofloxacin / Moxifloxacin</b></mark> + <mark class=\"hl rx\"><b>Prednisone / Dexamethasone</b></mark> (especially in <mark class=\"hl lab\"><b>Age &gt; 60 yrs, CKD, or Organ Transplant</b></mark> !).</li>\n<li class=\"l1\"><b>Consequence:</b> Sudden <b>Achilles Tendinitis &amp; Complete Tendon Rupture</b> (plus increased <b>Aortic Aneurysm rupture</b> risk in elderly!).</li>\n</ul><h3><b>3. Oral Absorption &amp; Chelation Traps (</b><b>\"Separated by 2–4 Hours!\"</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Mechanism:</b> Polyvalent cations (<b>Calcium, Iron, Magnesium/Aluminum Antacids, Zinc, Sucralfate, Dairy</b>) bind drugs in the gut forming insoluble unabsorbable complexes!</li>\n<li class=\"l1\"><b>Drugs Whose Absorption Is Ruined (Must Take Separately!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Levothyroxine</b></mark> (take on empty stomach 30–60 min before breakfast; <mark class=\"hl rx\"><b>separate 4 hrs from Iron, Calcium, PPIs</b></mark> !).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Fluoroquinolones</b> (Ciprofloxacin/Levofloxacin) &amp; <b>Tetracyclines</b> (Doxycycline — also binds milk/dairy!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Bisphosphonates</b> (Alendronate — must take ONLY with plain water!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Oral Iron</b> (avoid tea, coffee, milk, calcium, antacids, &amp; PPIs — take with Vitamin C!).</span></p><h3><b>4. Drugs That Cause Oral Contraceptive Pill (COC) Failure (</b><b>Unintended Pregnancy!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Culprits (Potent CYP3A4 Inducers):</b> <b>Rifampin / Rifabutin</b> (#1 most potent!), <b>Carbamazepine</b>, <b>Phenytoin</b>, <b>Phenobarbital</b>, <b>Topiramate (&gt; 200 mg)</b>, <b>Modafinil</b>,</li>\n</ul>\n<p><b>St. John’s Wort</b>, <b>Griseofulvin</b>! <i>(Note: Common antibiotics like Amoxicillin/Azithromycin do NOT reduce COC efficacy — Rifampin is the key antibiotic exception!)</i> -&gt; Recommend <b>Copper IUD, LNG-IUD, or DMPA</b> instead!</p><nav class=\"un\"><button class=\"nv\" data-u=\"u388\">← Module 4</button><button class=\"nv\" data-u=\"u390\">Module 6 →</button></nav></article><article class=\"view unit\" id=\"u390\" hidden style=\"--c:#00695c\"><button class=\"back\" data-p=\"15\">← Lab &amp; Drug Interactions</button><header class=\"uh\"><span class=\"ul\">Module 6</span><h1>Master CYP450 Table, Drug-Disease Contraindications &amp; Pregnancy Teratogens</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Master+CYP450+Table%2C+Drug-Disease+Contraindications+%26+Pregnancy+Teratogens+medical\">🔍 Search on Google</a></header><h3><b>1. Classic CYP450 Inducers vs. Inhibitors (Memorize These Two Lists!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>POTENT INDUCERS (Lower levels of Warfarin, DOACs, COCs, Statins, Steroids, Tacrolimus) — Mnemonic: \"CRAP GPS\":</b></mark></li>\n<li class=\"l2\"><b>C</b>arbamazepine | <b>R</b>ifampin | <b>A</b>lcohol (chronic) | <b>P</b>henytoin | <b>G</b>riseofulvin | <b>P</b>henobarbital | <b>S</b>t. John’s Wort &amp; <b>S</b>moking (CYP1A2 -&gt; drops Theophylline/Olanzapine/Clozapine!).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>POTENT INHIBITORS (Raise drug levels -&gt; TOXICITY!) — Mnemonic: \"SICKFACES.COM\":</b></mark></li>\n<li class=\"l2\"><b>S</b>odium Valproate | <b>I</b>soniazid | <b>C</b>imetidine | <b>K</b>etoconazole / <b>F</b>luconazole | <b>A</b>miodarone | <b>C</b>iprofloxacin | <b>E</b>rythromycin / <b>C</b>larithromycin | <b>S</b>ulfonamides (TMP-SMX) | <b>C</b>yclosporine | <b>O</b>meprazole | <b>M</b>etronidazole | (+ <b>Grapefruit Juice &amp; Ritonavir</b>!).</li>\n</ul><h3><b>2. Critical Drug-Disease Contraindications (\"NEVER GIVE X IN Y!\")</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Patient Condition</b></p></th><th><p><b>STRICTLY AVOID</b></p></th><th><p><b>Reason / Fatal Consequence</b></p></th></tr><tr><td><p><mark class=\"hl lab\"><b>Asthma / Severe COPD</b></mark></p></td><td><p>Non-selective <b>Beta-blockers</b> (Propranolol, Timolol eye drops!), <mark class=\"hl rx\"><b>Aspirin/NSAIDs</b></mark> (if AERD!), <mark class=\"hl rx\"><b>Adenosine</b></mark></p></td><td><p>Severe refractory bronchospasm! <i>(If BB needed in mild asthma/CAD -&gt; cardioselective Bisoprolol/Metoprolol cautiously!)</i></p></td></tr><tr><td><p><mark class=\"hl lab\"><b>G6PD Deficiency (Favism)</b></mark></p></td><td><p><b>TMP-SMX, Primaquine, Dapsone, Nitrofurantoin, Rasburicase, Methylene Blue</b></p></td><td><p>Acute massive intravascular hemolysis!</p></td></tr><tr><td><p><b>Myasthenia Gravis</b></p></td><td><p><mark class=\"hl rx\"><b>Aminoglycosides, Fluoroquinolones, Macrolides, Magnesium Sulfate, Beta-blockers</b></mark></p></td><td><p>Precipitates fatal <b>Myasthenic Respiratory Crisis</b>!</p></td></tr><tr><td><p><mark class=\"hl lab\"><b>Cirrhosis / Ascites / CKD / HF</b></mark></p></td><td><p><mark class=\"hl rx\"><b>NSAIDs</b></mark> (Ibuprofen, Diclofenac, Ketorolac)</p></td><td><p><mark class=\"hl lab\"><b>AKI</b></mark> , Hepatorenal syndrome, Variceal GI bleed, Acute HF decompensation!</p></td></tr><tr><td><p><b>eGFR &lt; 30 mL/min/1.73 m²</b></p></td><td><p><mark class=\"hl rx\"><b>Metformin</b></mark> , <b>Nitrofurantoin</b>, <b>Bisphosphonates</b>, <mark class=\"hl rx\"><b>Dabigatran/Rivaroxaban</b></mark> (avoid/adjust), <mark class=\"hl rx\"><b>Spironolactone</b></mark></p></td><td><p>Lactic acidosis (Metformin), peripheral neuropathy/ineffectiveness (Nitrofurantoin), hyperkalemia!</p></td></tr><tr><td><p><b>Children &lt; 16–18 Yrs (Viral Illness)</b></p></td><td><p><mark class=\"hl rx\"><b>Aspirin</b></mark> <i>(except Kawasaki/ARF!)</i></p></td><td><p><b>Reye’s Syndrome</b> (fulminant hepatic failure + cerebral edema!)</p></td></tr><tr><td><p><b>Pregnant Women (Teratogens!)</b></p></td><td><p><mark class=\"hl rx\"><b>ACE-i / ARBs, Warfarin, Isotretinoin, Methotrexate, Valproate, Lithium (1st trim), Tetracyclines, Fluoroquinolones, Statins, Misoprostol</b></mark></p></td><td><p>Fetal renal dysplasia (ACE-i), nasal/CNS defects (Warfarin), severe NTDs (Valproate), teeth staining (Tetracyclines), uterine rupture!</p></td></tr></table><p class=\"muted\"><i>End of Part 15B — Drug Interactions &amp; Prescribing Safety Complete!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u389\">← Module 5</button></nav></article>"});
